import pathlib,struct,hashlib,json,os,tempfile
def analyze(tx_pcap,rx_pcap,output):
    tx=pathlib.Path(tx_pcap).resolve();rx=pathlib.Path(rx_pcap).resolve();out=pathlib.Path(output).resolve()
    if out in (tx,rx):raise ValueError('output must not alias an input')
    def checksum(data):
        if len(data)%2:data+=b'\0'
        total=sum(struct.unpack('!%dH'%(len(data)//2),data))
        while total>>16:total=(total&65535)+(total>>16)
        return (~total)&65535
    def parse(path):
        raw=path.read_bytes()
        if len(raw)<24:raise ValueError('short PCAP')
        order={b'\xd4\xc3\xb2\xa1':'<',b'\xa1\xb2\xc3\xd4':'>'}.get(raw[:4])
        if order is None:raise ValueError('microsecond classic PCAP required')
        major,minor,zone,sigfigs,snap,link=struct.unpack(order+'HHIIII',raw[4:24])
        if (major,minor)!=(2,4) or link!=1 or not 64<=snap<=65535:raise ValueError('unsupported capture header')
        cursor=24;rows={}
        while cursor<len(raw):
            if cursor+16>len(raw):raise ValueError('short record header')
            seconds,micros,captured,original=struct.unpack(order+'IIII',raw[cursor:cursor+16]);cursor+=16
            if micros>=1000000 or captured!=original or captured>snap or cursor+captured>len(raw):raise ValueError('truncated or invalid capture')
            frame=raw[cursor:cursor+captured];cursor+=captured
            if len(frame)<34 or frame[12:14]!=b'\x08\x00':raise ValueError('Ethernet IPv4 required')
            packet=frame[14:];ihl=(packet[0]&15)*4
            if packet[0]>>4!=4 or ihl<20 or len(packet)<ihl or packet[9]!=17:raise ValueError('IPv4 UDP required')
            length=struct.unpack('!H',packet[2:4])[0]
            if length<ihl+8 or length>len(packet) or checksum(packet[:ihl])!=0:raise ValueError('invalid IPv4 header')
            if struct.unpack('!H',packet[6:8])[0]&0x3fff:raise ValueError('fragmented packet unsupported')
            datagram=packet[ihl:length];sport,dport,udp_length,wire=struct.unpack('!HHHH',datagram[:8])
            if udp_length!=len(datagram):raise ValueError('UDP length mismatch')
            pseudo=packet[12:20]+b'\0\x11'+struct.pack('!H',udp_length)
            state='absent' if wire==0 else ('valid' if checksum(pseudo+datagram)==0 else 'invalid')
            identity=(packet[12:16].hex(),packet[16:20].hex(),sport,dport,struct.unpack('!H',packet[4:6])[0])
            if identity in rows:raise ValueError('ambiguous reused packet identity')
            rows[identity]={'checksum':state,'payload_sha256':hashlib.sha256(datagram[8:]).hexdigest(),'payload_bytes':len(datagram)-8}
            if len(rows)>64:raise ValueError('capture limit')
        return rows
    left=parse(tx);right=parse(rx);items=[]
    for identity in sorted(set(left)|set(right)):
        a=left.get(identity);b=right.get(identity)
        if a is None or b is None:state='unpaired'
        elif a['payload_sha256']!=b['payload_sha256'] or a['payload_bytes']!=b['payload_bytes']:state='content_mismatch'
        elif 'absent' in (a['checksum'],b['checksum']):state='checksum_not_present'
        elif b['checksum']=='invalid':state='receiver_invalid'
        elif a['checksum']=='invalid':state='offload_candidate'
        else:state='consistent_valid'
        items.append({'identity':list(identity),'tx':a,'rx':b,'classification':state})
    result={'items':items,'offload_proven':False,'loss_proven':False}
    fd,name=tempfile.mkstemp(prefix='.pcap-review-',dir=out.parent)
    try:
        with os.fdopen(fd,'w') as stream:json.dump(result,stream,sort_keys=True)
        os.replace(name,out)
    finally:
        if os.path.exists(name):os.unlink(name)
    return result
